function validate([nums, edges]) {
  if (!Array.isArray(nums) || nums.length < 3 || nums.length > 1000) return 'nums needs 3 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000000)) return 'Each value is between 1 and 10^8.';
  const n = nums.length;
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'A tree on n nodes has exactly n - 1 edges.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) x = root[x] = root[root[x]]; return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge endpoints must be nodes 0 to n - 1.';
    if (a === b) return 'An edge cannot join a node to itself.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'The edges must form a tree (no cycles or repeated edges).';
    root[ra] = rb;
  }
  return null;
}

