function minimumScore(nums, edges) {
  const n = nums.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  const parent = new Array(n).fill(-1);
  const enter = new Array(n).fill(0);
  const order = [];
  const stack = [0];
  while (stack.length > 0) {
    const node = stack.pop();
    enter[node] = order.length;
    order.push(node);
    for (const next of graph[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        stack.push(next);
      }
    }
  }

  const subtreeXor = nums.slice();
  const size = new Array(n).fill(1);
  for (let i = n - 1; i > 0; i--) {
    const node = order[i];
    subtreeXor[parent[node]] ^= subtreeXor[node];
    size[parent[node]] += size[node];
  }

  const total = subtreeXor[0];
  let best = Infinity;
  for (let a = 1; a < n; a++) {
    for (let b = a + 1; b < n; b++) {
      let first = subtreeXor[a];
      let second = subtreeXor[b];
      let rest = total ^ first ^ second;
      if (enter[a] < enter[b] && enter[b] < enter[a] + size[a]) {
        first = subtreeXor[a] ^ subtreeXor[b];
        rest = total ^ subtreeXor[a];
      } else if (enter[b] < enter[a] && enter[a] < enter[b] + size[b]) {
        second = subtreeXor[b] ^ subtreeXor[a];
        rest = total ^ subtreeXor[b];
      }
      const score = Math.max(first, second, rest) - Math.min(first, second, rest);
      best = Math.min(best, score);
    }
  }
  return best;
}

