function minimumScore(nums, edges) {
  // Delete every pair of edges, rebuild the pieces with union-find, and score them directly.
  const n = nums.length;
  let best = Infinity;
  for (let i = 0; i < edges.length; i++) {
    for (let j = i + 1; j < edges.length; j++) {
      const root = Array.from({ length: n }, (_, k) => k);
      const find = x => (root[x] === x ? x : (root[x] = find(root[x])));
      edges.forEach(([a, b], k) => { if (k !== i && k !== j) root[find(a)] = find(b); });
      const piece = new Map();
      for (let v = 0; v < n; v++) piece.set(find(v), (piece.get(find(v)) ?? 0) ^ nums[v]);
      const values = [...piece.values()];
      best = Math.min(best, Math.max(...values) - Math.min(...values));
    }
  }
  return best;
}

