function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 101) : 3 + Math.floor(rand() * 6);
  const shape = Math.floor(rand() * 4);
  const top = large ? (rand() < 0.5 ? 100000000 : 1 + Math.floor(rand() * 64)) : (rand() < 0.8 ? 8 : 100000000);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  // Build a tree on shuffled labels: a path, a star, a broom, or a random attachment tree.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) {
    let p;
    if (shape === 0) p = i - 1;
    else if (shape === 1) p = 0;
    else if (shape === 2) p = i < n / 2 ? i - 1 : Math.floor(rand() * (n / 2));
    else p = Math.floor(rand() * i);
    edges.push(rand() < 0.5 ? [label[i], label[p]] : [label[p], label[i]]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [nums, edges];
}
